import logging

import abc
import six
from taf.transport.ssh import connect

from ute_ue.exceptions import ProhibitedInstanceError

from taf.ue.plugin.viavi.Exception import PPPoEConnectionError

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


def get_instance(ip, uname, pwd, pppd_server_type):
    if pppd_server_type.lower() == "windows":
        return WindowsPPPDServer(ip, uname, pwd)
    elif pppd_server_type.lower() == "linux":
        return LinuxPPPDServer(ip, uname, pwd)
    else:
        msg = ("Specify valid pppd_server_type property under data transfer in the configuration file."
               " Currently supported values are Linux and Windows")
        raise ProhibitedInstanceError(msg)


@six.add_metaclass(abc.ABCMeta)
class PPPDServer():
    @abc.abstractmethod
    def __init__(self):
        pass

    @abc.abstractmethod
    def pppoe_status(self):
        pass

    @abc.abstractmethod
    def pppoe_connect(self):
        pass

    @abc.abstractmethod
    def pppoe_disconnect(self):
        pass


class LinuxPPPDServer(PPPDServer):
    '''
    Connects to linux pppd server

    '''

    def __init__(self, ip, uname, pwd):
        """
        Establishes ssh connection to the pppd server
        :param ip:
        :param uname:
        :param pwd:
        """
        self.ssh = connect(ip, uname, pwd)

    def pppoe_status(self):
        raise NotImplementedError

    def pppoe_connect(self, command):
        """
        Executes the command
        :param command:
        :return:
        """
        self.ssh.send_command(command)
        if self.ssh.exit_code != 0:
            msg = "Execution of pppoe connection command {} failed".format(command)
            raise PPPoEConnectionError(msg)
        logger.debug("Execution of {} command is successful".format(command))

    def pppoe_disconnect(self, command=None):
        """
            kills all pppd connections on the server
            :return:
        """
        self.ssh.send_command("killall pppd")
        if self.ssh.exit_code != 0:
            logger.debug("Failed Execution of killall pppd command with exit code {}".format(self.ssh.exit_code))
            return
        logger.debug("Execution of killall pppd command is successful")


class WindowsPPPDServer(PPPDServer):
    '''
    Connects to linux pppd server

    '''

    def __init__(self, ip, uname, pwd):
        """
        Establishes ssh connection to the pppd server
        :param ip: IPV4 Address of Windows Server to connect through SSH
        :param uname:   user name SSH connectivity
        :param pwd:     password SSH connectivity
        """
        self.ssh = connect(ip, uname, pwd)

    def pppoe_status(self):
        raise NotImplementedError

    def pppoe_connect(self, connection_name):
        rasdial_command = "RASDIAL {connection_name}".format(connection_name=connection_name)
        self.ssh.send_command(rasdial_command)
        if self.ssh.exit_code != 0:
            msg = "Execution of pppoe connection command {} failed".format(rasdial_command)
            raise PPPoEConnectionError(msg)
        logger.debug("Execution of {} command is successful".format(rasdial_command))

    def pppoe_disconnect(self, connection_name):
        rasdial_command = "RASDIAL {connection_name} /disconnect".format(connection_name=connection_name)
        self.ssh.send_command(rasdial_command)
        if self.ssh.exit_code != 0:
            msg = "Execution of pppoe connection command {} failed".format(rasdial_command)
            raise PPPoEConnectionError(msg)
        logger.debug("Execution of {} command is successful".format(rasdial_command))
